INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('9847f4a7-af90-4a88-852b-194d725081ec', '{f1c11505-b54f-4037-8414-444417b1c5d5}', '{"kz": "Газеттер мен журналдардағы жарияланымдар", "ru": "Публикации в газетах и журналах"}', 'megaphone', '{"kz": "Мұғалімнің газеттерде, журналдарда, онлайн басылымдарда және басқа да БАҚ-та жарияланымдарын қосуға арналған бөлім.", "ru": "Раздел для добавления публикаций преподавателя в газетах, журналах, интернет-изданиях и других СМИ."}', '2026-05-26 11:28:36.679679+00', '2026-06-08 10:53:19.427869+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('15128cd6-5f2b-4df5-b702-1aef46853b24', '{571d169a-e25b-4349-b65a-b56ca1aaa6b0}', '{"kz": "Білім сапасы", "ru": "Открытые уроки"}', 'notebook-text', '{"kz": "Өткізілген ашық сабақтарды қосуға және әріптестердің сабақтарына қатысуға арналған бөлім.", "ru": "Раздел для добавления проведённых открытых занятий и посещения уроков коллег."}', '2026-05-26 11:16:57.291584+00', '2026-06-08 10:53:40.833768+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('44444444-4444-4444-8444-444444444448', '{769415c0-4041-4205-95cf-6c0059d5af30}', '{"kz": "Тәрбие жұмысы", "ru": "Воспитательная работа"}', 'graduation-cap', '{"kz": "Топтық жұмысты, тәлімгерлікті, тәлімгерлік сағаттарын және студенттердің іс-шараларға қатысуын қосуға арналған бөлім.", "ru": "Раздел для добавления работы с группой, кураторства, воспитательных часов и участия студентов в мероприятиях."}', '2026-05-20 12:42:03.004591+00', '2026-06-08 10:58:39.084422+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('cced00d7-ee5f-48c9-8fd8-e885ad6bffcb', '{155f99cb-ff4c-4e0f-8ee1-677e4b7c4f52}', '{"kz": "Алғыс хаттар", "ru": "Благодарственные письма"}', 'star', '{"kz": "Сертификаттарды, алғыс хаттарды, мақтау қағаздарын және басқа да мұғалімдерге берілетін марапаттарды қосуға арналған бөлім.", "ru": "Раздел для добавления грамот, благодарственных писем, похвальных листов и других наград преподавателя."}', '2026-05-25 11:53:07.09105+00', '2026-06-08 10:54:00.82562+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('c871b6aa-ec1a-411a-aac5-da24fa217f35', '{21c41e1d-c906-4212-8194-005a5ee16e12,6b8e7106-a4e9-4ee6-b7c0-a057e28ced2b,49b98075-79b8-4c1e-95d2-9f373a0a1210,658ec17e-d703-476e-a8ea-5f70c5db2c26}', '{"kz": "Жарыстар мен байқаулардың нәтижелері", "ru": "Результаты конкурсов и соревнований"}', 'award', '{"kz": "Мұғалімнің байқауларға, жарыстарға және кәсіби іс-шараларға қатысуын қосуға арналған бөлім.", "ru": "Раздел для добавления участия преподавателя в конкурсах, соревнованиях и профессиональных мероприятиях."}', '2026-05-25 11:27:35.302646+00', '2026-06-09 09:31:16.327584+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('360e0501-0fd8-461c-9b0a-0fab015feaad', '{70529ec4-8933-4b79-aeb7-be672c449454}', '{"kz": "Мансаптық бағдар беру іс-шаралары", "ru": "Профориентационная деятельность"}', 'projector', '{"kz": "", "ru": ""}', '2026-06-03 04:51:17.959528+00', '2026-06-10 13:45:17.91156+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('44444444-4444-4444-8444-444444444447', '{29ff7f54-4af4-4537-a520-1b4931c01035}', '{"kz": "Оқу-әдістемелік материалдар", "ru": "Учебно-методические материалы"}', 'book', '{"kz": "Кәсіпорындармен жұмысты, өндірістік оқытуды, тағылымдамаларды және жасалған меморандумдарды қосуға арналған бөлім.", "ru": "Раздел для добавления методических материалов, учебных программ, пособий и других образовательных разработок преподавателя."}', '2026-05-20 12:42:03.004591+00', '2026-06-10 09:29:56.732131+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('95533907-4f22-490f-ba55-39b6064e44b9', '{cfd0371e-6e3e-463a-bab8-64eef5d29ea5}', '{"kz": "Оқу және өндірістік жұмыстарға қатысу", "ru": "Участие в учебно-производственной работе"}', 'handshake', '{"kz": "Колледждің жұмыс топтарына, комитеттеріне, жобаларына және басқа да ұйымдастырушылық жұмыстарына қатысуды қосуға арналған бөлім.", "ru": "Раздел для добавления участия в рабочих группах, комиссиях, проектах и другой организационной работе колледжа."}', '2026-05-26 12:34:43.026088+00', '2026-06-10 09:51:49.310774+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('44444444-4444-4444-8444-444444444441', '{67f54cb3-903e-4945-b10d-4b65ce8b6cd7}', '{"kz": "Біліктілікті арттыру, тағылымдама", "ru": "Повышения квалификации, стажировка"}', 'briefcase', '{"kz": "Мұғалімдерге арналған курстарды, тағылымдамаларды, сертификаттарды және басқа да кәсіби дайындықтарды қосуға арналған бөлім.", "ru": "Раздел для добавления курсов, стажировок, сертификатов и другого профессионального обучения преподавателя."}', '2026-05-20 12:42:03.004591+00', '2026-06-10 10:01:23.635873+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('44444444-4444-4444-8444-444444444443', '{cc112dd3-73fe-4eb1-8d2c-fa4dfa3f80ff,1392839e-d0ce-4d20-bb2a-42aba7eb797c}', '{"kz": "Конференцияларда, семинарларда және іс-шараларда сөз сөйлеу", "ru": "Выступления в конференциях, семинарах, мероприятиях"}', 'presentation', '{"kz": "Мұғалім қатысатын сөздерді, баяндамаларды, семинарларды, конференцияларды және басқа да іс-шараларды қосуға арналған бөлім.", "ru": "Раздел для добавления выступлений, докладов, семинаров, конференций и других мероприятий с участием преподавателя."}', '2026-05-20 12:42:03.004591+00', '2026-06-10 10:02:13.555587+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('44444444-4444-4444-8444-444444444446', '{07b48031-af7a-4b2c-ab68-5d89176b9b23}', '{"kz": "Топтарға, жобаларға қатысу", "ru": "Участие в группах, проектах"}', 'users', '{"kz": "", "ru": ""}', '2026-05-20 12:42:03.004591+00', '2026-06-11 07:27:20.423634+00');
INSERT INTO public.award_categories (id, award_types, name, icon, description, created_at, updated_at) VALUES ('11a8b017-b25f-470c-8ef3-751c4708fe25', '{0a31934b-19ff-4b07-b378-fcc4ff3384b9}', '{"kz": "Телеарналарға сұхбаттар", "ru": "Интервью для телевизионных каналов"}', 'speech', '{"kz": "Мұғалімнің газеттердегі, теледидардағы, веб-сайттардағы және басқа да БАҚ-тағы сұхбаттарын қосуға арналған бөлім.", "ru": "Раздел для добавления интервью преподавателя в газетах, на телевидении, сайтах и других средствах массовой информации."}', '2026-06-03 13:08:06.890448+00', '2026-06-08 13:27:35.726633+00');
