INSERT INTO public.rup_exploration_notes (id, basis, goals, competencies, prerequisites, postrequisites, internet_resources, technical_resources) VALUES ('5d49dd9e-6a96-47df-bd4d-ed0b6c80b5d4', '{"kz": "asf", "ru": "Рабочая учебная программа по профессиональному модулю разработана на основе Приказа Министра просвещения Республики Казахстан от 3 августа 2022 года №348, учитывая внесенные изменения от 15.04.2025 года, профессиональных стандартов НПП «Атамекен» по квалификации «Web-дизайнер», а также стандартов WorldSkills для специальности «06130100 Программное обеспечение» и квалификации «3W06130102 Web-дизайнер»."}', '{"kz": "asf", "ru": "Целью освоения профессионального модуля является формирование у обучающихся профессиональных компетенций, необходимых для работы с базами данных MySQL, включая проектирование, создание, администрирование и оптимизацию баз данных. Обучающиеся должны приобрести теоретические знания и практические навыки по работе с СУБД MySQL, включая разработку SQL-запросов, обеспечение целостности данных, резервное копирование и восстановление, а также основы обеспечения безопасности баз данных."}', '{"kz": "asf", "ru": "Формируемые компетенции: владение методами и средствами администрирования баз данных MySQL; работа с SQL-запросами для управления данными; соблюдение требований к обеспечению безопасности баз данных; установка, настройка и управление системой управления базами данных MySQL."}', '{"kz": "asf", "ru": "ПМ6 PostgreSql"}', '{"kz": "asf", "ru": "."}', '{f272faac-010d-4ec0-a7e3-65469d1f3ca9,3994c1c7-9485-4a0b-8acf-aa626dbf5a6d,d294e550-207c-4388-ae49-f820cb5b3796,cb482f57-d5e9-4fc8-b426-2c63f04c1b43,39db5461-51f6-449b-b42e-611d1d8cab57,69aee7ba-319d-4614-8f05-43576a304318}', '{89054b65-c8ff-4a66-9d5e-df517452d0da,0d3d4d7b-19ec-46ba-84e7-bf82d88b835f,f202b4b6-6412-4513-8e21-dd89b4b93be6,382b700d-bb24-4cd1-8ad8-b257b1837cac,fe0b408e-dc83-4045-9271-ea66eddc292a}');
